#include <stdexcept>

template <typename T, std::size_t Capacity = 128>
class CircularStack {
    std::array<T, Capacity> data_{};
    std::size_t top_ = 0;

public:
    constexpr void push(const T& value) {
        if (top_ >= Capacity) throw std::overflow_error("CircularStack overflow");
        data_[top_++] = value;
    }

    constexpr T pop() {
        if (top_ == 0) throw std::underflow_error("CircularStack underflow");
        return data_[--top_];
    }

    [[nodiscard]] constexpr std::size_t size() const noexcept {
        return top_;
    }
};
